 // OMEGA-BLOCK-START
 // Computes C = A * B. C is NOT zeroed by the caller. Any number of threads may be
 // used (std::thread is available); n is any size from 1 to 2048.
+namespace {
+constexpr int IBLOCK = 64;
+constexpr int KBLOCK = 64;
+
+void row_block(int n, int i0, int i1, const float* A, const float* B, float* C) {
+    // Zero the rows this thread owns.
+    for (int i = i0; i < i1; ++i) {
+        float* Crow = C + (size_t)i * n;
+        for (int j = 0; j < n; ++j) Crow[j] = 0.0f;
+    }
+
+    // Packed panel of B rows for the current k tile: [k_tile][j].
+    std::vector<float> panel((size_t)KBLOCK * n);
+
+    for (int k0 = 0; k0 < n; k0 += KBLOCK) {
+        int k_end = std::min(k0 + KBLOCK, n);
+        int kk = k_end - k0;
+
+        // Pack B[k0:k_end][0:n] contiguously.
+        for (int kk2 = 0; kk2 < kk; ++kk2) {
+            const float* Brow = B + (size_t)(k0 + kk2) * n;
+            float* prow = panel.data() + (size_t)kk2 * n;
+            for (int j = 0; j < n; ++j) prow[j] = Brow[j];
+        }
+
+        for (int i = i0; i < i1; ++i) {
+            const float* Arow = A + (size_t)i * n;
+            float* Crow = C + (size_t)i * n;
+            for (int kk2 = 0; kk2 < kk; ++kk2) {
+                float a = Arow[k0 + kk2];
+                const float* Brow = panel.data() + (size_t)kk2 * n;
+                int j = 0;
+#if defined(__ARM_NEON)
+                for (; j + 3 < n; j += 4) {
+                    float32x4_t va = vdupq_n_f32(a);
+                    float32x4_t vb = vld1q_f32(Brow + j);
+                    float32x4_t vc = vld1q_f32(Crow + j);
+                    vc = vfmaq_f32(vc, va, vb);
+                    vst1q_f32(Crow + j, vc);
+                }
+#endif
+                for (; j < n; ++j) {
+                    Crow[j] += a * Brow[j];
+                }
+            }
+        }
+    }
+}
